<template>
  <div class="app-container agent-page">
    <div class="page-heading"><div><h2>安全策略</h2><p>集中查看 Agent 工具、外部连接、执行策略和审批边界。</p></div><el-tag type="info" effect="plain">只读策略快照</el-tag></div>
    <el-row :gutter="14" class="summary-row"><el-col :xs="24" :sm="12" :lg="6" v-for="item in policyCards" :key="item.key"><el-card shadow="never" class="summary-card"><div class="summary-label">{{ item.label }}</div><div class="summary-value" :class="item.tone">{{ item.value }}</div></el-card></el-col></el-row>
    <el-row :gutter="14"><el-col :xs="24" :lg="12"><el-card shadow="never"><template #header>执行边界</template><el-descriptions :column="1" border><el-descriptions-item label="工作流模板读取">{{ onOff(policy.workflowTemplateEnabled) }}</el-descriptions-item><el-descriptions-item label="模型 Planner">{{ onOff(policy.plannerModelEnabled) }}</el-descriptions-item><el-descriptions-item label="运行时模型重规划">{{ onOff(policy.runtimePlannerModelEnabled) }}</el-descriptions-item><el-descriptions-item label="平台最大步骤">{{ policy.platformMaxSteps || '-' }}</el-descriptions-item><el-descriptions-item label="平台最大 Token">{{ policy.platformMaxTokens || '-' }}</el-descriptions-item><el-descriptions-item label="平台最大费用">${{ money(policy.platformMaxCost) }}</el-descriptions-item><el-descriptions-item label="任意 Shell / SQL / SSH">禁止</el-descriptions-item><el-descriptions-item label="自动生产部署">禁止</el-descriptions-item></el-descriptions></el-card></el-col><el-col :xs="24" :lg="12"><el-card shadow="never"><template #header>外部连接就绪度</template><el-descriptions :column="1" border><el-descriptions-item v-for="item in externalConnectors" :key="item.key" :label="item.label"><el-tag :type="item.value ? 'success' : 'info'">{{ item.value ? '已配置' : '未配置' }}</el-tag></el-descriptions-item></el-descriptions></el-card></el-col></el-row>
    <el-card shadow="never" class="quota-card"><template #header>平台日配额状态</template><el-descriptions :column="3" border><el-descriptions-item label="今日任务">{{ external.dailyBudgetUsage?.taskCount || 0 }} / {{ policy.dailyMaxTasks || '不限' }}</el-descriptions-item><el-descriptions-item label="今日 Token">{{ external.dailyBudgetUsage?.tokenUsage || 0 }} / {{ policy.dailyMaxTokens || '不限' }}</el-descriptions-item><el-descriptions-item label="今日费用">${{ money(external.dailyBudgetUsage?.costUsage) }} / {{ policy.dailyMaxCost ? `$${money(policy.dailyMaxCost)}` : '不限' }}</el-descriptions-item></el-descriptions></el-card>
    <el-card shadow="never" class="alerts-card"><template #header>当前告警</template><el-alert v-for="item in alerts" :key="`${item.code}-${item.message}`" :title="item.message" :type="alertType(item.severity)" :closable="false" show-icon /><el-empty v-if="!alerts.length" description="暂无告警" /></el-card>
  </div>
</template>
<script setup name="JgAgentSecurity">
import { getAgentSecurity } from '@/api/jiugai/agentConfig'
const policy = ref({}); const external = ref({}); const alerts = ref([]); const loading = ref(false)
const externalConnectors = computed(() => ['apiRequest', 'webSearch', 'browser', 'mcp', 'codeRunner'].map(key => ({ key, label: externalLabel(key), value: !!external.value[key] })))
const policyCards = computed(() => [{ key: 'tools', label: '启用工具', value: policy.value.toolReadiness?.enabledTools || 0 }, { key: 'approval', label: '需审批工具', value: policy.value.toolReadiness?.approvalRequired || 0 }, { key: 'alerts', label: '当前告警', value: alerts.value.length, tone: alerts.value.length ? 'warning' : '' }, { key: 'shell', label: '任意 Shell', value: '禁止', tone: 'safe' }])
function onOff(value) { return value ? '已启用' : '关闭' }; function money(value) { const number = Number(value || 0); return Number.isFinite(number) ? number.toFixed(2) : '0.00' }; function alertType(value) { return value === 'CRITICAL' ? 'error' : value === 'WARNING' ? 'warning' : 'info' }; function externalLabel(key) { return ({ apiRequest: 'API Request', webSearch: 'Web Search', browser: 'Browser', mcp: 'MCP', codeRunner: 'Code Runner' })[key] || key }
async function load() { loading.value = true; try { const response = await getAgentSecurity(); const data = response.data || {}; policy.value = { ...(data.executionPolicies || {}), toolReadiness: data.toolReadiness || {} }; external.value = data.externalReadiness || {}; alerts.value = data.alerts || [] } finally { loading.value = false } }
onMounted(load)
</script>
<style scoped>
.agent-page { color: #1f2937; }.page-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; margin-bottom: 18px; }.page-heading h2 { margin: 0 0 6px; font-size: 22px; }.page-heading p { margin: 0; color: #6b7280; }.summary-row { margin-bottom: 14px; }.summary-card { min-height: 92px; }.summary-label { color: #6b7280; font-size: 13px; }.summary-value { margin-top: 10px; color: #1f2937; font-size: 22px; font-weight: 600; }.summary-value.warning { color: #d97706; }.summary-value.safe { color: #15803d; }.quota-card, .alerts-card { margin-top: 14px; }.alerts-card :deep(.el-alert + .el-alert) { margin-top: 8px; }
</style>
